1	package cli
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
11		"os"
12		"path/filepath"
13		"sort"
14		"strings"
15		"time"
16	
17		"github.com/entireio/entire-brain/factmerge"
18		"github.com/entireio/entire-brain/internal/cli/internal/base"
19	)
20	
21	const (
22		factsDirName          = "facts"
23		factsTaxonomyFileName = "taxonomy.json"
24		factsTaxonomyPath     = factsDirName + "/" + factsTaxonomyFileName
25		factsFileName         = "facts.ndjson"
26		factsMaxPerChunk      = 6 // quality-gate output cap per source chunk
27	
28		factOriginDistilled = "distilled"
29		factOriginAuthored  = "authored"
30	)
31	
32	// factRecord (factmerge.Record) and factAnchor (factmerge.Anchor) are defined
33	// as type aliases in facts_aliases.go; the durable-fact data model now lives in
34	// factmerge.
35	
36	// factTaxonomy is the active taxonomy snapshot. Paths are validated against
37	// factPathPattern; classification may only invent a new three-level path under
38	// an existing top-level category.
39	type factTaxonomy struct {
40		GeneratedAt time.Time         `json:"generated_at"`
41		Categories  map[string]string `json:"categories"` // top-level -> description
42		Paths       []factPathDef     `json:"paths"`
43	}
44	
45	type factPathDef struct {
46		Path        string   `json:"path"`
47		Description string   `json:"description"`
48		Examples    []string `json:"examples,omitempty"`
49	}
50	
51	// normalizeFactText, factRecordID, validFactPath, and normalizeFactPaths moved
52	// to factmerge (NormalizeText/RecordID/ValidPath/NormalizePaths); the
53	// CLI names are forwarding wrappers in facts_aliases.go.
54	
55	// factTopLevel returns the top-level category of a taxonomy path (the segment
56	// before the first dot), or "" if the path is empty.
57	func factTopLevel(path string) string {
58		if i := strings.IndexByte(path, '.'); i >= 0 {
59			return path[:i]
60		}
61		return path
62	}
63	
64	// --- on-disk layout -------------------------------------------------------
65	
66	// factsBranchRelDir returns the brain-relative directory holding a branch's
67	// facts. The readable slug alone is not collision-free — distinct branches can
68	// sanitize to the same slug (e.g. "evis/search" and "evis-search", or "Main"
69	// and "main") — and two branches sharing a facts file would clobber each other
70	// and break branch isolation. A short hash of the full branch name is appended
71	// so each branch maps to a stable, unique directory while staying greppable.
72	func factsBranchRelDir(branch string) string {
73		slug := safePathComponent(branch, "branch", 80)
74		sum := sha256.Sum256([]byte(branch))
75		return filepath.ToSlash(filepath.Join(factsDirName, slug+"-"+hex.EncodeToString(sum[:4])))
76	}
77	
78	func factsFileRelPath(branch string) string {
79		return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsFileName))
80	}
81	
82	// factBranchStoreExists reports whether the brain actually holds a facts.ndjson
83	// for a branch.
84	//
85	// loadFacts deliberately returns an empty slice for a missing file so first-run
86	// callers need no special case, which means every read surface reports a
87	// misspelled branch exactly as it reports a real branch with nothing on it.
88	// Wherever that difference matters — naming a promote endpoint, say — this is
89	// the check that tells the two apart.
90	func factBranchStoreExists(brainDir, branch string) bool {
91		if brainDir == "" || branch == "" {
92			return false
93		}
94		_, err := os.Stat(filepath.Join(brainDir, filepath.FromSlash(factsFileRelPath(branch))))
95		return err == nil
96	}
97	
98	// loadFacts reads a branch's facts.ndjson. A missing file is not an error: it
99	// yields an empty slice so first-run callers do not special-case it. Blank
100	// lines are skipped; a malformed line is a hard error so a corrupt store is
101	// surfaced rather than silently dropping records.
102	func loadFacts(brainDir, branch string) ([]factRecord, error) {
103		rel := factsFileRelPath(branch)
104		if err := base.RejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
105			return nil, err
106		}
107		path := filepath.Join(brainDir, filepath.FromSlash(rel))
108		if info, err := os.Lstat(path); err == nil && !info.Mode().IsRegular() {
109			return nil, fmt.Errorf("fact store is not a regular file: %s", rel)
110		}
111		records, err := parseFactsFile(path)
112		if err != nil {
113			// The bare parse error names the damage but not the repair, and this
114			// is the error every read surface shows a user. Name the repair here,
115			// once, the way the history index names `refresh history`.
116			// parseFactsFile itself stays clean so the integrity report (which
117			// quotes it inside a fuller sentence) does not say it twice.
118			return nil, fmt.Errorf("%w; %s", err, factsRepairHint())
119		}
120		return records, nil
121	
122	}
123	
124	// parseFactsFile reads a facts.ndjson file at an absolute path. A missing file
125	// yields an empty slice; a malformed line is a hard error so a corrupt store is
126	// surfaced rather than silently dropping records. The byte-level scan lives in
127	// factmerge.ParseNDJSON; this keeps only the file/path handling and restores the
128	// historical "parse <file> line N: ..." message the core cannot know the path
129	// for.
130	func parseFactsFile(path string) ([]factRecord, error) {
131		f, err := os.Open(path)
132		if err != nil {
133			if os.IsNotExist(err) {
134				return nil, nil
135			}
136			return nil, err
137		}
138		defer f.Close()
139		records, err := factmerge.ParseNDJSON(f)
140		if err != nil {
141			var perr *factmerge.ParseError
142			if errors.As(err, &perr) {
143				return nil, fmt.Errorf("parse %s line %d: %w", filepath.Base(path), perr.Line, perr.Err)
144			}
145			return nil, err
146		}
147		return records, nil
148	}
149	
150	// missingFactBranchStores returns the branches a fact source manifest declares
151	// whose facts.ndjson is no longer on disk.
152	//
153	// loadFacts treats an absent file as an empty branch (first-run callers must
154	// not special-case it), so a deleted or never-restored fact store is
155	// indistinguishable from "this branch has no facts" on every read surface.
156	// The manifest, however, names exactly which branches the store is supposed to
157	// hold, and that claim is checkable. Anything it names but cannot produce is a
158	// source that will silently contribute nothing.
159	func missingFactBranchStores(brainDir string, source *factSourceManifest) []string {
160		if source == nil || brainDir == "" {
161			return nil
162		}
163		var missing []string
164		for _, branch := range source.Branches {
165			if branch == "" {
166				continue
167			}
168			path := filepath.Join(brainDir, filepath.FromSlash(factsFileRelPath(branch)))
169			if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
170				missing = append(missing, branch)
171			}
172		}
173		return missing
174	}
175	
176	// unreadableFactBranchStore is one declared branch whose facts.ndjson is on
177	// disk but cannot be read back.
178	type unreadableFactBranchStore struct {
179		Branch string
180		Err    error
181	}
182	
183	// unreadableFactBranchStores returns the declared branches whose facts.ndjson
184	// exists but does not parse.
185	//
186	// Existence is not readability. `facts status`, `recall`, `brief` and every
187	// other fact reader goes through loadFacts, which fails hard on a malformed
188	// line so a corrupt store is never silently truncated -- so a single bad line
189	// takes the whole branch out of every retrieval surface while the manifest,
190	// the file listing, and therefore missingFactBranchStores all still report the
191	// store as present. Doctor is the command a user is sent to when `status` says
192	// something is wrong, and it must not hand out a clean bill of health for a
193	// store every other command refuses to read.
194	//
195	// This deliberately calls the SAME loader those commands call rather than
196	// scanning the file itself: a second, more forgiving parser here would put
197	// doctor back in the business of disagreeing with the readers it is supposed
198	// to explain.
199	func unreadableFactBranchStores(brainDir string, source *factSourceManifest) []unreadableFactBranchStore {
200		if source == nil || brainDir == "" {
201			return nil
202		}
203		var unreadable []unreadableFactBranchStore
204		for _, branch := range source.Branches {
205			if branch == "" {
206				continue
207			}
208			if _, err := loadFacts(brainDir, branch); err != nil {
209				unreadable = append(unreadable, unreadableFactBranchStore{Branch: branch, Err: err})
210			}
211		}
212		return unreadable
213	}
214	
215	// missingFactStoreWarning renders the caller-facing warning for the branches
216	// missingFactBranchStores found, or "" when the declared store is intact.
217	func missingFactStoreWarning(missing []string) string {
218		if len(missing) == 0 {
219			return ""
220		}
221		return fmt.Sprintf(
222			"facts declared for branch(es) %s but their %s is missing from the brain; those facts cannot be recalled — run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"` and re-distill",
223			strings.Join(missing, ", "), factsFileName,
224		)
225	}
226	
227	// writeFacts persists a branch's facts as newline-delimited JSON, one record
228	// per line, sorted deterministically so the file is stable across rebuilds and
229	// diffs cleanly. The branch directory is created if needed. The byte-level
230	// sort+marshal lives in factmerge.WriteNDJSON; this keeps the atomic,
231	// symlink-rejecting disk write in the CLI.
232	func writeFacts(brainDir, branch string, records []factRecord) error {
233		var buf bytes.Buffer
234		if err := factmerge.WriteNDJSON(&buf, records); err != nil {
235			return err
236		}
237		return brainstore.WriteBrainRelativeFileAtomic(brainDir, factsFileRelPath(branch), buf.Bytes(), 0o600)
238	}
239	
240	// --- taxonomy -------------------------------------------------------------
241	
242	// defaultFactTaxonomy is the shipped baseline taxonomy. The top-level
243	// categories here are fixed in Phase A; distillation may invent a new
244	// three-level path only under one of these categories. The brain regenerates
245	// taxonomy.json from this default on refresh.
246	func defaultFactTaxonomy(now time.Time) factTaxonomy {
247		return factTaxonomy{
248			GeneratedAt: now,
249			Categories: map[string]string{
250				"preferences":  "How the user wants to work and how code should be written.",
251				"architecture": "Resolved design, boundary, and data-flow decisions and their rationale.",
252				"project":      "Stack, tooling, CI/CD, ownership, and standing project facts.",
253				"workflow":     "Branching, testing, review, and release process rules.",
254				"constraints":  "Non-obvious invariants, gotchas, and hard constraints.",
255			},
256			Paths: []factPathDef{
257				{Path: "preferences.coding.style", Description: "Stated code-style preferences.", Examples: []string{"prefers table-driven tests"}},
258				{Path: "preferences.workflow.general", Description: "How the user prefers to work day to day."},
259				{Path: "architecture.boundaries.rationale", Description: "Why a module or package boundary exists."},
260				{Path: "architecture.data.flow", Description: "How data moves through the system."},
261				{Path: "project.tooling.stack", Description: "Languages, frameworks, and tools the project uses."},
262				{Path: "project.ci_cd.pipeline", Description: "Build, test, and deploy pipeline facts."},
263				{Path: "workflow.branching.rules", Description: "Branching and merge conventions."},
264				{Path: "workflow.testing.rules", Description: "How and when tests must be run."},
265				{Path: "constraints.invariants.general", Description: "Invariants that must hold across changes."},
266			},
267		}
268	}
269	
270	// loadFactTaxonomy reads the active taxonomy snapshot, falling back to the
271	// shipped default when the file is absent so callers always get a usable
272	// taxonomy. A present-but-malformed file is a hard error.
273	func loadFactTaxonomy(brainDir string, now time.Time) (factTaxonomy, error) {
274		path := filepath.Join(brainDir, filepath.FromSlash(factsTaxonomyPath))
275		data, err := os.ReadFile(path)
276		if err != nil {
277			if os.IsNotExist(err) {
278				return defaultFactTaxonomy(now), nil
279			}
280			return factTaxonomy{}, err
281		}
282		var taxonomy factTaxonomy
283		if err := json.Unmarshal(data, &taxonomy); err != nil {
