333	// summarizeFactSource folds a per-branch view of the fact store into the
334	// source manifest recorded under sources.facts in the brain manifest.
335	func summarizeFactSource(now time.Time, byBranch map[string][]factRecord, chunksScanned, chunksDistilled, proposals int, warnings []string) *factSourceManifest {
336		source := &factSourceManifest{
337			GeneratedAt:     now,
338			TaxonomyPath:    factsTaxonomyPath,
339			Proposals:       proposals,
340			ChunksScanned:   chunksScanned,
341			ChunksDistilled: chunksDistilled,
342			Warnings:        append([]string(nil), warnings...),
343			ByKind:          map[string]int{},
344		}
345		branches := make([]string, 0, len(byBranch))
346		for branch := range byBranch {
347			branches = append(branches, branch)
348		}
349		sort.Strings(branches)
350		source.Branches = branches
351		for _, branch := range branches {
352			for _, record := range byBranch[branch] {
353				// A stored line carrying no id is not a fact (see isFactRecord): it
354				// cannot be fetched, recalled, verified or superseded. Counting it
355				// here is how a damaged store re-declared its own damage as healthy
356				// on the next `remember` or `refresh`, and it is what the integrity
357				// cross-check compares against.
358				if !isFactRecord(record) {
359					continue
360				}
361				if record.Status == factStatusCandidate {
362					// A staged candidate is not a published memory yet: counting it
363					// into Facts would inflate every surface after a crashed run,
364					// while hiding it would make the staged work invisible. Its own
365					// counter keeps both honest until the next distill reconciles it.
366					source.PendingReconcile++
367					continue
368				}
369				source.Facts++
370				switch record.Origin {
371				case factOriginDistilled:
372					source.Distilled++
373				case factOriginAuthored:
374					source.Authored++
375				case factOriginImported:
376					// Without this bucket an imported fact raises the total and no
377					// line item, so the origins visibly do not sum to the count and
378					// nothing explains the difference.
379					source.Imported++
380				}
381				if record.Status == factStatusSuperseded {
382					source.Superseded++
383				}
384				// by_kind counts only active facts, matching what recall/tree surface
385				// (superseded/retracted facts are not retrievable), so the histogram
386				// answers "what kinds can I recall" rather than paralleling Facts.
387				if record.Status == factStatusActive {
388					source.ByKind[factKindOrInferred(record)]++
389				}
390				for _, anchor := range record.Provenance {
391					if anchor.Verified {
392						source.Verified++
393					} else {
394						source.Unsigned++
395					}
396				}
397			}
398		}
399		return source
400	}
