402	// missingFactStoreWarningForBranch scopes retrieval warnings to the store read.
403	func missingFactStoreWarningForBranch(brainDir string, source *factSourceManifest, branch string) string {
404		integrity := inspectFactStore(brainDir, source)
405		switch integrity.Mode {
406		case factStoreDefectMissing:
407			for _, missing := range integrity.Missing {
408				if missing == branch {
409					return missingFactStoreWarning([]string{branch})
410				}
411			}
412			return ""
413		case factStoreDefectUnreadable:
414			for _, unreadable := range integrity.Unreadable {
415				if unreadable == branch {
416					return integrity.Warning()
417				}
418			}
419			return ""
420		default:
421			// Aggregate count discrepancies cannot be assigned to one branch.
422			return integrity.Warning()
423		}
424	}
