11	// factScopeCrossCutting marks facts about how work is done (preferences,
12	// workflow) — they apply repo-wide and are noise for a specific technical
13	// lookup. factScopeLocal marks facts tied to code/subsystems (architecture,
14	// constraints) and standing project facts.
15	const (
16		factScopeCrossCutting = "cross-cutting"
17		factScopeLocal        = "local"
18	)
19	
20	// crossCuttingTopLevels are the taxonomy categories that describe ways of
21	// working rather than the code itself.
22	var crossCuttingTopLevels = map[string]struct{}{
23		"preferences": {},
24		"workflow":    {},
25	}
26	
27	// factScope classifies a fact as cross-cutting or local from its taxonomy
28	// paths. A fact is cross-cutting only when every path is a cross-cutting
29	// category; any code/constraint/project path makes it local (the technical
30	// substance wins). This is the scope-tiering signal: separate "how we work"
31	// from "what this code is", so a technical lookup is not buried under generic
32	// preference and workflow facts.
33	func factScope(paths []string) string {
34		if len(paths) == 0 {
35			return factScopeLocal
36		}
37		for _, p := range paths {
38			if _, ok := crossCuttingTopLevels[factTopLevel(p)]; !ok {
39				return factScopeLocal
40			}
41		}
42		return factScopeCrossCutting
43	}
44	
45	// The fixed KIND set (Appendix D) — factKind* consts, the validFactKinds set,
46	// and validFactKind — moved to factmerge (Kind* / ValidFactKind). The
47	// CLI names are aliases/wrappers in facts_aliases.go, so the inference and
48	// filtering below (which stay here because they depend on semanticRecord and
49	// other CLI-only surfaces) reference them unchanged.
50	
51	// gotchaCues / invariantCues are high-precision phrases that override the
52	// taxonomy prior in inferFactKind. They are deliberately narrow: a wrong
53	// override is worse than falling back to the topic prior, and the agent path is
54	// the accurate source going forward.
55	var gotchaCues = []string{"gotcha", "footgun", "pitfall", "careful", "watch out", "easy to miss", "easy to forget", "don't forget", "beware", "subtle bug", "surprising", "counterintuitive", "fails silently", "silently fails", "breaks if", "only works if"}
56	
57	// closedNegativeCues mark a settled-negative: something tried/considered and
58	// rejected with evidence. Checked before gotchaCues — a dead end phrased as a
59	// trap is still a dead end, and the closed-negative framing carries the
60	// revisit-when trigger a future session needs.
61	var closedNegativeCues = []string{"do not re-litigate", "dead end", "ruled out", "decided against", "rejected because", "was rejected", "measured as noise", "not a lever", "within noise", "abandoned because", "didn't work because", "did not work because", "tried and failed", "made no difference", "no measurable", "revisit only if", "revisit when"}
62	
63	var invariantCues = []string{"must not", "must always", "must ", "never ", "always ", "is required", "are required", "invariant", "guaranteed", "may not ", "cannot ", "has to "}
64	
65	// topLevelToKind maps a taxonomy top-level category to its default KIND, or ""
66	// for an unknown category.
67	func topLevelToKind(topLevel string) string {
68		switch topLevel {
69		case "preferences":
70			return factKindPreference
71		case "workflow":
72			return factKindConvention
73		case "constraints":
74			return factKindInvariant
75		case "architecture", "project":
76			return factKindDecision
77		}
78		return ""
79	}
80	
81	// factKindPriority breaks ties when a multi-path fact maps to several kinds: the
82	// more specific/actionable kind wins, so a constraint co-tagged with
83	// architecture infers invariant rather than the weaker decision default.
84	var factKindPriority = map[string]int{
85		factKindClosedNegative: 6,
86		factKindGotcha:         5,
87		factKindInvariant:      4,
88		factKindPreference:     3,
89		factKindConvention:     2,
90		factKindDecision:       1,
91	}
92	
93	// inferFactKind deterministically classifies a fact's KIND from its taxonomy
94	// paths (the prior) refined by a few high-precision text cues. This is the
95	// no-agent backfill path and the fallback when the agent omits/violates the
96	// kind; it is heuristic by design — B4's eval is the guardrail. A gotcha cue
97	// wins over everything (a constraint phrased as a trap is a gotcha); otherwise
98	// the highest-priority kind across the fact's paths wins, so the invariant
99	// signal of a `constraints.*` path is never lost to an alphabetically-earlier
100	// co-tag. Allocates nothing — the hot read path calls this per fact.
101	func inferFactKind(paths []string, text string) string {
102		lower := strings.ToLower(text)
103		for _, cue := range closedNegativeCues {
104			if strings.Contains(lower, cue) {
105				return factKindClosedNegative
106			}
107		}
108		for _, cue := range gotchaCues {
109			if strings.Contains(lower, cue) {
110				return factKindGotcha
111			}
112		}
113		best := ""
114		for _, p := range paths {
115			if k := topLevelToKind(factTopLevel(p)); k != "" && (best == "" || factKindPriority[k] > factKindPriority[best]) {
116				best = k
117			}
118		}
119		if best != "" {
120			return best
121		}
122		// No (or unknown) taxonomy signal: let an invariant cue pull it off the
123		// decision default.
124		for _, cue := range invariantCues {
125			if strings.Contains(lower, cue) {
126				return factKindInvariant
127			}
128		}
129		return factKindDecision
130	}
131	
132	// factKindOrInferred returns a fact's stored Kind when present and valid, else
133	// the deterministic inference. Read surfaces use this so a not-yet-backfilled
134	// fact still classifies consistently.
135	func factKindOrInferred(f factRecord) string {
136		if validFactKind(f.Kind) {
137			return strings.ToLower(strings.TrimSpace(f.Kind))
138		}
139		return inferFactKind(f.Paths, f.Text)
