170	// nilIfEmpty normalizes an empty slice to nil so an absent locus is omitted from
171	// JSON (omitempty) and compares equal across runs.
172	func nilIfEmpty(s []string) []string {
173		if len(s) == 0 {
174			return nil
175		}
176		return s
177	}
178	
179	// equalStrings reports whether two string slices are element-wise equal. Both
180	// loci are produced by factLocus (sorted, deduped), so order is canonical.
181	func equalStrings(a, b []string) bool {
182		if len(a) != len(b) {
183			return false
184		}
185		for i := range a {
186			if a[i] != b[i] {
187				return false
188			}
189		}
190		return true
191	}
