193	// filterFactsByKind keeps only facts of the requested KIND (matching on the
194	// stored-or-inferred kind); an empty kind returns all.
195	func filterFactsByKind(facts []factRecord, kind string) []factRecord {
196		kind = strings.ToLower(strings.TrimSpace(kind))
197		if kind == "" {
198			return facts
199		}
200		out := facts[:0:0]
201		for _, f := range facts {
