209	// factsRelevantToChange ranks active facts whose locus names a changed file or a
210	// symbol defined in those files — the "changed files → relevant facts" tie-in
211	// between the durable-facts locus and the semantic graph. files are the changed
212	// paths; symbols are the semantic symbols in those files (already resolved by
213	// the caller). Ranked by overlap count, then recency, capped at limit.
214	func factsRelevantToChange(files []string, symbols []semanticRecord, facts []factRecord, limit int) []factRecord {
215		if limit <= 0 {
216			limit = 10
217		}
218		target := map[string]struct{}{}
219		add := func(s string) {
220			if s = strings.ToLower(strings.TrimSpace(s)); len(s) >= 3 {
221				target[s] = struct{}{}
222			}
223		}
224		for _, f := range files {
225			add(f)
226			add(filepath.Base(f))
227		}
228		for _, s := range symbols {
229			add(s.Name)
230			add(s.QualifiedName)
231		}
232		if len(target) == 0 {
233			return nil
234		}
235		type scored struct {
236			rec factRecord
237			n   int
238		}
239		var hits []scored
240		for _, f := range facts {
241			if f.Status != factStatusActive {
242				continue
243			}
244			n := 0
245			for _, tok := range base.FactLocusOf(f) {
246				if _, ok := target[tok]; ok {
247					n++
248				}
249			}
250			if n > 0 {
251				hits = append(hits, scored{f, n})
252			}
253		}
254		sort.SliceStable(hits, func(i, j int) bool {
255			if hits[i].n != hits[j].n {
256				return hits[i].n > hits[j].n
257			}
258			return hits[i].rec.UpdatedAt.After(hits[j].rec.UpdatedAt)
259		})
260		out := make([]factRecord, 0, min(limit, len(hits)))
261		for _, h := range hits {
262			out = append(out, h.rec)
263			if len(out) >= limit {
264				break
265			}
266		}
267		return out
268	}
269	
270	// filterFactsByLocus keeps facts whose locus intersects the query's locus (a
271	// path/glob/symbol). An empty query returns all. The query is run through
272	// factLocus so a path or CamelCase symbol normalizes the same way the stored
273	// loci did.
274	func filterFactsByLocus(facts []factRecord, locus string) []factRecord {
275		locus = strings.TrimSpace(locus)
276		if locus == "" {
