262	// TestFactLocusKeepsHyphenatedPaths pins the bug ashtom reported: the
263	// extractor used to cut a hyphenated path into fragments, so a fact about
264	// `website/scripts/pre-build.ts` was anchored to "website/scripts/pre" and
265	// "build.ts" — two tokens that name nothing in the repo — while the real path
266	// never appeared at all. Quoting the path in backticks did not help: the
267	// backtick span added the correct token, but the regex sweep still produced
268	// the fragments beside it, which is exactly what he saw.
269	func TestFactLocusKeepsHyphenatedPaths(t *testing.T) {
270		cases := []struct {
271			name string
272			text string
273			want string
274		}{
275			{"bare", "the website/scripts/pre-build.ts hook runs first", "website/scripts/pre-build.ts"},
276			{"backticked", "see `website/scripts/pre-build.ts` for the hook", "website/scripts/pre-build.ts"},
277			{"no directory", "pre-build.ts runs before the bundle step", "pre-build.ts"},
278			{"hyphenated directory", "entire-brain/internal/cli/facts_locus.go owns this", "entire-brain/internal/cli/facts_locus.go"},
279			{"leading dot", "edit .github/workflows/ci-windows.yml to add the shard", ".github/workflows/ci-windows.yml"},
280			{"dotted repo config", "the flag lives in .entire/settings.json", ".entire/settings.json"},
281		}
282		for _, c := range cases {
283			t.Run(c.name, func(t *testing.T) {
284				got := base.FactLocus(c.text)
285				loc := map[string]bool{}
286				for _, l := range got {
287					loc[l] = true
288				}
289				if !loc[c.want] {
290					t.Errorf("expected locus token %q in %v", c.want, got)
291				}
292				// The fragments are the defect, not merely a missing token: a
293				// fragment is a plausible-looking path that resolves to nothing,
294				// which is worse than no anchor at all.
295				for _, frag := range []string{"website/scripts/pre", "build.ts", "brain/internal/cli/facts_locus.go", "github/workflows/ci", "windows.yml", "entire/settings.json"} {
296					if frag == c.want {
297						continue
298					}
299					if loc[frag] {
300						t.Errorf("fragment %q leaked into locus %v", frag, got)
301					}
302				}
303			})
304		}
305	}
