23	// decodersAllowedToRejectUnknownFields are the only files that may call
24	// DisallowUnknownFields directly. Everything reading the brain's own persisted
25	// state goes through brainstore.DecodeVersionedJSONBody or the dedicated
26	// file-backed manifest decoder, both of which force each caller to say
27	// whether it is guarding a rewrite or only reading — the distinction this
28	// package got wrong. Each entry carries its reason at the call site.
29	var decodersAllowedToRejectUnknownFields = map[string]string{
30		"internal/manifest/read.go": "dedicated file-backed manifest decoder: strict rewrites, tolerant read retry with unknown-field reporting",
31		"export.go":                 "user-authored settings, where an unknown key is usually a typo",
