70	// The recovery this health report recommends has to actually work: a manifest
71	// carrying another build's fields stays readable and refuses rewrites, and
72	// removing it lets the next refresh rebuild it.
73	func TestBrainManifestSkewIsReadOnlyAndRecoverableByRemoval(t *testing.T) {
74		t.Parallel()
75	
76		dir := writeTestManifest(t, `{"schema_version":3,"repo_key":"gh/entirehq/devenv","retired_field":0}`)
77		rebuilt := exportManifest{SchemaVersion: bmanifest.SchemaVersion, RepoKey: "gh/entirehq/devenv"}
78	
