80			t.Fatalf("skewed manifest must stay readable: %v", err)
81		}
82		if err := writeBrainManifestAndReadme(dir, rebuilt); err == nil {
83			t.Fatal("a writer must not re-encode a manifest whose fields it never saw")
84		}
