94	// manifestBrainWrite matches a write of the manifest back into the brain
95	// directory: a write-named helper taking the brain dir and the manifest name.
96	// It deliberately does not match a manifest packed into a bundle tar, which
97	// copies a freshly built value rather than rewriting live state.
98	var manifestBrainWrite = regexp.MustCompile(`(?i)write[A-Za-z]*\(\s*(outputDir|brainDir)\s*,\s*bmanifest.FileName`)
99	
100	// Every file that rewrites the manifest into the brain directory gates on the
101	// strict reader.
102	//
103	// The tolerant reader exists for the ~280 call sites that only consume the
104	// manifest, but three writers used bmanifest.Load's strictness as their write
105	// guard and two of them are nowhere near writeBrainManifestAndReadme. Making the
106	// reader tolerant silently disarmed those two: the bytes they write are
107	// marshalled from a struct, so a field the reader dropped would be erased. This
108	// discovers writers by scanning, so a new one cannot quietly inherit the wrong
109	// reader.
110	func TestEveryManifestWriterGatesOnTheStrictReader(t *testing.T) {
111		t.Parallel()
112	
113		entries, err := os.ReadDir(".")
114		if err != nil {
115			t.Fatal(err)
116		}
117		writers := 0
118		for _, entry := range entries {
119			name := entry.Name()
120			if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
121				continue
122			}
123			source, err := os.ReadFile(name)
124			if err != nil {
125				t.Fatal(err)
126			}
127			text := string(source)
128			if !manifestBrainWrite.MatchString(text) {
129				continue
130			}
131			writers++
132			if !strings.Contains(text, "bmanifest.LoadForReplace") {
133				t.Errorf("%s rewrites the brain manifest but never calls bmanifest.LoadForReplace; a writer "+
134					"gated on the tolerant bmanifest.Load erases fields another build wrote", name)
135			}
136		}
137		if writers < 3 {
138			t.Fatalf("found %d manifest writers, want at least the 3 known ones; the detection pattern has drifted", writers)
139		}
140	}
